with base as (select *, coalesce(quantity, 0) as quantity_filled, cast(quantity as string) as quantity_num from order_items where product_id is not null) select case when quantity >= 9 then 'PREMIUM' else 'STANDARD' end as quantity_tier, order_id, round(avg(unit_price), 2) as avg_unit_price, round(avg(quantity_filled), 2) as avg_quantity_filled, grouping_id() as grouping_id from base group by rollup (case when quantity >= 9 then 'PREMIUM' else 'STANDARD' end, order_id) having avg_quantity_filled > 0 order by avg_quantity_filled desc;
